signature.code:
function useFieldArray(path: string): {
  fields: ArrayFieldEntry[];
  append / prepend / insert / remove / swap / move
}

examples.code:
function Tags() {
  const { fields, append, remove } = useFieldArray("tags");
  return (
    <ul>
      {fields.map((f) => (
        <li key={f.id}>
          {String(f.item)}
          <button type="button" onClick={() => remove(f.index)}>×</button>
        </li>
      ))}
      <button type="button" onClick={() => append("new")}>Add</button>
    </ul>
  );
}
